from agent import *from models.products import *import reimport httplibhttplib._MAXHEADERS = 200def run(context: dict[str, str], session: Session):    session.queue(Request('https://www.filmrecensiepagina.nl/films-filmoverzicht.htm', use='curl', force_charset='cp1252'), process_revlist, dict())def process_revlist(data: Response, context: dict[str, str], session: Session):    revs = data.xpath('//p[@align="center"]/font/a[not(contains(@href, "updates1"))]')    for rev in revs:        name = rev.xpath('text()').string()        url = rev.xpath('@href').string()        if name and url:            session.queue(Request(url, use='curl', force_charset='cp1252'), process_review, dict(name=name, url=url))    # no next pagedef process_review(data: Response, context: dict[str, str], session: Session):    product = Product()    product.name = context['name']    product.url = context['url']    product.ssid = product.url.split('/')[-1].replace('.html', '').replace('.htm', '')    product.category = 'Films'    review = Review()    review.title = product.name    review.url = product.url    review.ssid = product.ssid    review.type = 'pro'    date = data.xpath('//blockquote/p//text()[normalize-space()]').string(multiple=True)    if not date:        date = data.xpath('//p[.//img[contains(@src, "pinkpan.gif")]]/following-sibling::p//text()[normalize-space(.)]').string(multiple=True)    if date:        date = re.search(r'\(?\s*\d{4}\)?', date)        if date:            review.date = date.group(0).strip('( \n)')    author = data.xpath('//blockquote/p//text()[normalize-space()]').string(multiple=True)    if not author:        author = data.xpath('//p[.//img[contains(@src, "pinkpan.gif")]]/following-sibling::p//text()[normalize-space(.)]').string(multiple=True)    if author:        author = re.search(r'(van.*?)(?:\(?\d{4}\)?)', author, re.DOTALL)        if author:            author = author.group(1).split(' van')[-1].split('(')[0].split('regisseurs')[-1].split('regisseur')[-1].split(' Zomer')[0].strip()            review.authors.append(Person(name=author, ssid=author))    excerpt = data.xpath('//blockquote/p//text()[normalize-space()]').string(multiple=True)    if not excerpt:        excerpt = data.xpath('//p[.//img[contains(@src, "pinkpan.gif")]]/following-sibling::p[following-sibling::h3[.//img[contains(@src, "pinkpan.gif")]]]//text()[normalize-space()]').string(multiple=True)    if excerpt:        excerpt = re.split(r'\(\s*\d+\)', excerpt)[-1].strip(' \n.')        if excerpt:            review.add_property(type='excerpt', value=excerpt)            product.reviews.append(review)            session.emit(product)